#include "painter.hpp"
#include "display.hpp"
namespace ui {
/* Compact glyph source retained only as a browser-port fallback. The drawing
 * cell is the upstream 8x16 metric; exact upstream fixed_8x16 bytes remain an
 * explicitly tracked asset-convergence item. */
#define G(a,b,c,d,e,f,g) ((uint64_t)(a)|((uint64_t)(b)<<5)|((uint64_t)(c)<<10)|((uint64_t)(d)<<15)|((uint64_t)(e)<<20)|((uint64_t)(f)<<25)|((uint64_t)(g)<<30))
static uint64_t glyph_bits(char c){if(c>='a'&&c<='z')c=(char)(c-'a'+'A');switch(c){
case 'A':return G(14,17,17,31,17,17,17);case 'B':return G(15,17,17,15,17,17,15);case 'C':return G(14,17,1,1,1,17,14);case 'D':return G(15,17,17,17,17,17,15);case 'E':return G(31,1,1,15,1,1,31);case 'F':return G(31,1,1,15,1,1,1);case 'G':return G(14,17,1,29,17,17,14);case 'H':return G(17,17,17,31,17,17,17);case 'I':return G(14,4,4,4,4,4,14);case 'J':return G(28,8,8,8,8,9,6);case 'K':return G(17,9,5,3,5,9,17);case 'L':return G(1,1,1,1,1,1,31);case 'M':return G(17,27,21,21,17,17,17);case 'N':return G(17,19,21,25,17,17,17);case 'O':return G(14,17,17,17,17,17,14);case 'P':return G(15,17,17,15,1,1,1);case 'Q':return G(14,17,17,17,21,9,22);case 'R':return G(15,17,17,15,5,9,17);case 'S':return G(30,1,1,14,16,16,15);case 'T':return G(31,4,4,4,4,4,4);case 'U':return G(17,17,17,17,17,17,14);case 'V':return G(17,17,17,17,17,10,4);case 'W':return G(17,17,17,21,21,21,10);case 'X':return G(17,17,10,4,10,17,17);case 'Y':return G(17,17,10,4,4,4,4);case 'Z':return G(31,16,8,4,2,1,31);
case '0':return G(14,17,19,21,25,17,14);case '1':return G(4,6,4,4,4,4,14);case '2':return G(14,17,16,8,4,2,31);case '3':return G(15,16,16,14,16,16,15);case '4':return G(8,12,10,9,31,8,8);case '5':return G(31,1,1,15,16,16,15);case '6':return G(14,1,1,15,17,17,14);case '7':return G(31,16,8,4,2,2,2);case '8':return G(14,17,17,14,17,17,14);case '9':return G(14,17,17,30,16,16,14);
case '-':return G(0,0,0,31,0,0,0);case '.':return G(0,0,0,0,0,6,6);case ':':return G(0,6,6,0,6,6,0);case '/':return G(16,8,8,4,2,2,1);case '+':return G(0,4,4,31,4,4,0);case '>':return G(1,2,4,8,4,2,1);case '<':return G(16,8,4,2,4,8,16);case '[':return G(14,2,2,2,2,2,14);case ']':return G(14,8,8,8,8,8,14);case '!':return G(4,4,4,4,4,0,4);case '?':return G(14,17,16,8,4,0,4);case '_':return G(0,0,0,0,0,0,31);case '=':return G(0,31,0,31,0,0,0);case ' ':return 0;default:return G(31,17,4,4,4,0,4);}}
#undef G
int Painter::draw_char(Point p,const Style& style,char c){host::display.fill_rectangle({p,{8,16}},style.background);const uint64_t bits=glyph_bits(c);for(int row=0;row<7;++row){const uint8_t mask=(uint8_t)((bits>>(row*5))&31u);for(int col=0;col<5;++col)if(mask&(1u<<col))host::display.fill_rectangle({p.x()+1+col,p.y()+1+row*2,1,2},style.foreground);}return 8;}
int Painter::draw_string(Point p,const Style& style,const char* text,int max_chars){int width=0,count=0;while(text&&*text&&count<max_chars){const int adv=draw_char({p.x()+width,p.y()},style,*text++);width+=adv;++count;}return width;}
void Painter::draw_rectangle(Rect r,Color c){host::display.draw_rectangle(r,c);}void Painter::fill_rectangle(Rect r,Color c){host::display.fill_rectangle(r,c);}void Painter::draw_hline(Point p,int w,Color c){host::display.draw_hline(p,w,c);}void Painter::draw_vline(Point p,int h,Color c){host::display.draw_vline(p,h,c);}void Painter::draw_line(Point a,Point b,Color c){host::display.draw_line(a,b,c);}
}
